package com.honorablemobile
import org.junit.Assert.*
import org.junit.Test
import kotlin.random.Random
import kotlin.math.abs
class VideoAudioMatchTest {
 private fun clips(gain:Float=1f,refGain:Float=.5f)=listOf(VideoSegment(0,2000,volume=gain),VideoSegment(0,2000,sourceId="other",volume=refGain))
 private fun level(c:VideoSegment,rms:Double?,known:Long=c.endMs-c.startMs)=VideoAudioMatch.Level(c.sourceId,c.startMs,c.endMs,known,rms)
 private fun plan(c:List<VideoSegment>,a:Double=.8,b:Double=.2)=VideoAudioMatch.prepare(c,0,1,level(c[0],a),level(c[1],b))
 @Test fun lowerGainUsesReferenceVolumeAndWeightedSourceRms(){val c=clips();val p=plan(c);assertEquals(.125f,p.gain,0f);assertEquals(.1,p.targetRms,1e-12);assertEquals(.1,p.predictedRms,1e-12);assertEquals(.8,p.beforeRms,1e-12);assertFalse(p.capped);assertEquals(1f,c[0].volume,0f)}
 @Test fun gainCanRiseWithinOriginalLimitAndCapIsExplicit(){val c=clips(.1f,1f);val p=plan(c,.5,.2);assertEquals(.4f,p.gain,0f);assertFalse(p.capped);val capped=plan(clips(.2f,1f),.1,.8);assertEquals(1f,capped.gain,0f);assertTrue(capped.capped);assertTrue(capped.predictedRms<capped.targetRms)}
 @Test fun muteChoicesSilenceUnknownAndNonfiniteMeasurementsAreRefused(){for(c in listOf(clips(0f),clips(refGain=0f)))assertThrows(IllegalArgumentException::class.java){plan(c)};val c=clips();for(rms in listOf<Double?>(null,0.0,.001,-.1,1.001,Double.NaN,Double.POSITIVE_INFINITY)){assertThrows(IllegalArgumentException::class.java){VideoAudioMatch.prepare(c,0,1,level(c[0],rms),level(c[1],.2))};assertThrows(IllegalArgumentException::class.java){VideoAudioMatch.prepare(c,0,1,level(c[0],.8),level(c[1],rms))}};assertThrows(IllegalArgumentException::class.java){plan(clips(refGain=.05f),.8,.01)}}
 @Test fun coverageRequiresExactNinetyFivePercentAndValidCount(){val c=clips();assertEquals(.125f,VideoAudioMatch.prepare(c,0,1,level(c[0],.8,1900),level(c[1],.2,1900)).gain,0f);for(known in listOf(-1L,0L,1899L,2001L))assertThrows(IllegalArgumentException::class.java){VideoAudioMatch.prepare(c,0,1,level(c[0],.8,known),level(c[1],.2))}}
 @Test fun measurementsMustMatchExactSourceAndWindow(){val c=clips();for(m in listOf(level(c[0],.8).copy(sourceId="foreign"),level(c[0],.8).copy(startMs=1),level(c[0],.8).copy(endMs=2001)))assertThrows(IllegalArgumentException::class.java){VideoAudioMatch.prepare(c,0,1,m,level(c[1],.2))};assertThrows(IllegalArgumentException::class.java){VideoAudioMatch.prepare(c,0,1,level(c[0],.8),level(c[1],.2).copy(sourceId="primary"))}}
 @Test fun invalidReferenceNoopAndUnreachableAlreadyMaxedGainDoNotCreateChanges(){val c=clips(1f,1f);for(ref in listOf(-1,0,2))assertThrows(IllegalArgumentException::class.java){VideoAudioMatch.prepare(c,0,ref,level(c[0],.8),level(c[1],.2))};assertThrows(IllegalArgumentException::class.java){plan(c,.2,.2)};assertThrows(IllegalArgumentException::class.java){plan(c,.1,.8)};assertEquals(1f,c[0].volume,0f)}
 @Test fun eligibilityBoundsAreSourceTimeNotPlaybackDuration(){assertTrue(VideoAudioMatch.eligible(VideoSegment(0,120000,speed=.5f)));assertFalse(VideoAudioMatch.eligible(VideoSegment(0,120001,speed=2f)));assertTrue(VideoAudioMatch.eligible(VideoSegment(Int.MAX_VALUE-120000L,Int.MAX_VALUE.toLong())));assertFalse(VideoAudioMatch.eligible(VideoSegment(Int.MAX_VALUE-1000L,Int.MAX_VALUE.toLong()+1)))}
 @Test fun actualStreamingEnergyAndOverviewFeedThePlanAndUnknownIsNotSilence(){val c=listOf(VideoSegment(100,140),VideoSegment(200,240,sourceId="other"));val a=VideoAudioMatch.measure(c[0],listOf(VideoQuietWindow(100,120,.2),VideoQuietWindow(120,140,.6)));val b=VideoAudioMatch.measure(c[1],listOf(VideoQuietWindow(200,220,.2),VideoQuietWindow(220,240,.2)));val p=VideoAudioMatch.prepare(c,0,1,a,b);assertEquals(.2,p.targetRms,1e-12);assertEquals(.2,p.predictedRms,1e-8);val missing=VideoAudioMatch.measure(c[0],listOf(VideoQuietWindow(100,120,.2),VideoQuietWindow(120,140,null)));assertEquals(20L,missing.knownMs);assertThrows(IllegalArgumentException::class.java){VideoAudioMatch.prepare(c,0,1,missing,b)};assertThrows(IllegalArgumentException::class.java){VideoAudioMatch.measure(c[0],listOf(VideoQuietWindow(0,20,.2),VideoQuietWindow(20,40,.2)))}}
 @Test fun sameSourceSameWindowCanReuseMeasurementWhileGainsDiffer(){val c=listOf(VideoSegment(0,2000),VideoSegment(0,2000,volume=.5f));val measurement=level(c[0],.4);val p=VideoAudioMatch.prepare(c,0,1,measurement,measurement);assertEquals(.5f,p.gain,0f);assertSame(c[1],p.clips[1])}
 @Test fun randomizedPlansChangeOnlyGainAndApproachReferenceUnlessCapped(){val rng=Random(134);repeat(200){val c=clips(.123f,(.1+rng.nextDouble()*.9).toFloat());val a=.05+rng.nextDouble()*.95;val b=.05+rng.nextDouble()*.95;val p=plan(c,a,b);assertTrue(p.gain>0f&&p.gain<=1f);assertEquals(c[0].copy(volume=p.gain),p.clips[0]);assertSame(c[1],p.clips[1]);assertEquals(VideoPlaybackTime.durationUs(c),VideoPlaybackTime.durationUs(p.clips));assertTrue(p.predictedRms<=p.targetRms+1e-7);if(!p.capped)assertTrue(abs(p.predictedRms-p.targetRms)<1e-7)}}
 @Test fun realProjectSingleUndoPreservesAllAnnotationsReferenceSoundtrackAndCodec(){val old=VideoSegment(1000,3000,speed=1.5f,title="Keep",grade=VideoGrade(exposure=.5f),volume=1f,audioFade=true,fadeEdges=true,captions=listOf(VideoCaption(1500,2500,"Keep words")),captionSourceUri="content://synthetic/subtitles",motion=VideoMotion(enabled=true,endZoom=1.5f,anchorEndMs=5000));val ref=VideoSegment(0,2000,sourceId="other",volume=.5f);val p=VideoEditProject(10000);val music=VideoSoundtrack("content://synthetic/music",10000,loop=false);p.restore(listOf(old,ref),mapOf("other" to 2000L),music);val prepared=plan(p.segments,.5,.2);val request=VideoBatchReview(p.segments,music);val stage=Any();request.open(stage);request.propose(stage,prepared.clips);assertTrue(request.apply(stage,p){});assertEquals(old.copy(volume=prepared.gain),p.segments[0]);assertEquals(ref,p.segments[1]);assertEquals(music,p.soundtrack);assertTrue(p.undo());assertEquals(listOf(old,ref),p.segments);assertFalse(p.canUndo);assertTrue(p.redo());val draft=VideoDraft(10000,p.segments,0,1000,1000,3000,listOf(VideoSource("other","content://synthetic/other",2000)),music);assertEquals(draft,VideoDraftCodec.decode(VideoDraftCodec.encode(draft),10000));assertFalse(request.apply(stage,p){})}
 @Test fun staleForeignPausedAndDismissedApprovalsCannotApplyMeasuredGain(){for(mode in 0..3){val c=clips();val p=VideoEditProject(10000);p.restore(c,mapOf("other" to 2000L));val request=VideoBatchReview(p.segments,null);val stage=Any();request.open(stage);request.propose(stage,plan(c).clips);when(mode){0->{request.dismiss(stage);assertFalse(request.apply(stage,p){})};1->assertFalse(request.apply(Any(),p){});2->assertThrows(IllegalStateException::class.java){request.apply(stage,p){error("paused")}};3->{p.setTitle(0,"Changed");assertThrows(IllegalArgumentException::class.java){request.apply(stage,p){}}}};assertEquals(1f,p.segments[0].volume,0f)}}
}
